package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.config.*;import com.lianxibu.site.controller.collector.*;import com.lianxibu.site.domain.protocol.CanonicalJson;import com.lianxibu.site.repository.jobs.JdbcCollectorHostMemory;import com.lianxibu.site.service.identity.NodeIdentityService;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.context.annotation.Import;import org.springframework.context.support.GenericApplicationContext;
class CollectorHostMemoryHttpTest {
 @org.springframework.boot.test.context.TestConfiguration(proxyBeanMethods=false)
 @EnableAutoConfiguration(exclude=org.springframework.boot.jdbc.autoconfigure.DataSourceAutoConfiguration.class)
 @Import({CollectorHostMemoryController.class,CollectorSecurityConfiguration.class,BootstrapSecurityConfiguration.class})static class App{}
 CollectorHostMemoryServiceTest f;org.springframework.context.ConfigurableApplicationContext app;HttpClient client;String root;
 DataSource source(){return new CollectorHostMemoryServiceTest().source();}
 CollectorHostMemoryService memoryService(){return f.service;}
 @BeforeEach void setup()throws Exception{f=new CollectorHostMemoryServiceTest(){@Override DataSource source(){return CollectorHostMemoryHttpTest.this.source();}};f.setup();start(true);client=HttpClient.newHttpClient();}
 void start(boolean enabled){app=new SpringApplicationBuilder(App.class).properties("server.port=0","server.address=127.0.0.1","spring.main.banner-mode=off","logging.level.root=ERROR").initializers(context->{var registry=(GenericApplicationContext)context;registry.registerBean(NodeIdentityService.class,()->f.identity);registry.registerBean(CollectorHostMemoryService.class,this::memoryService);}).run("--site.collector.enabled=true","--site.browser.enabled=true","--site.ops.collector-memory.enabled="+enabled);root="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort()+"/api/collector/v1/host-memory";}
 @AfterEach void cleanup(){if(client!=null)client.close();if(app!=null)app.close();if(f!=null)f.cleanup();}
 HttpResponse<String> post(String token,String suffix,byte[] raw,boolean extra)throws Exception{var request=HttpRequest.newBuilder(URI.create(root+suffix)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(raw));if(token!=null)request.header("Authorization","Bearer "+token);if(extra)request.header("Idempotency-Key","fictional-unused-key");return client.send(request.build(),HttpResponse.BodyHandlers.ofString());}
 void code(HttpResponse<String> result,int status,String code){assertEquals(status,result.statusCode(),result.body());assertEquals(code,CanonicalJson.parse(result.body()).at("/error/code").asText());assertEquals("no-store",result.headers().firstValue("Cache-Control").orElseThrow());assertFalse(result.body().contains(f.token));assertFalse(result.body().contains("SELECT"));}
 @Test void actualHttpCurrentAuthorityAndClosedFourFieldAckReplayThenRevocation()throws Exception{var raw=f.raw(f.f.now,1,10);code(post(null,"",raw,false),401,"unauthenticated");code(post("B".repeat(43),"",raw,false),403,"forbidden");var result=post(f.token,"",raw,false);assertEquals(200,result.statusCode(),result.body());var data=CanonicalJson.parse(result.body()).get("data");assertEquals(4,data.size());assertEquals(f.f.epoch,data.get("capture_epoch").asText());assertEquals(1,data.get("sequence").asLong());assertEquals(f.f.body(f.f.now,1,10).payloadHash(),data.get("payload_hash").asText());assertEquals("2026-01-01T00:10:00.000000Z",data.get("received_at").asText());f.at.set(f.f.now.plusSeconds(600));assertEquals(data,CanonicalJson.parse(post(f.token,"",raw,false).body()).get("data"));assertNull(f.nodes.byTokenHash(com.lianxibu.site.domain.identity.NodeTokens.digest(f.token)).lastSeenAt());assertEquals(1,f.nodes.revoke(f.f.f.node,1));code(post(f.token,"",raw,false),403,"forbidden");}
 @Test void exactQueryHeadersDuplicateUnknownCapacityAndMissingValuesAreRejected()throws Exception{var raw=f.raw(f.f.now,1,10);code(post(f.token,"?unexpected=1",raw,false),400,"protocol_error");code(post(f.token,"",raw,true),400,"protocol_error");String text=new String(raw,StandardCharsets.UTF_8);for(String field:new String[]{"\"sequence\":1,","\"healthy\":true,"})code(post(f.token,"",text.replace("{","{"+field).getBytes(StandardCharsets.UTF_8),false),400,"protocol_error");code(post(f.token,"",text.replace("\"pid\":12","\"pid\":0").getBytes(StandardCharsets.UTF_8),false),422,"validation");code(post(f.token,"",new byte[8193],false),413,"payload_too_large");code(post(f.token,"",new byte[0],false),400,"protocol_error");var doubled=HttpRequest.newBuilder(URI.create(root)).header("Content-Type","application/json").header("Authorization","Bearer "+f.token).header("Authorization","Bearer "+f.token).POST(HttpRequest.BodyPublishers.ofByteArray(raw)).build();code(client.send(doubled,HttpResponse.BodyHandlers.ofString()),400,"protocol_error");assertNull(f.f.f.tx.execute(s->f.f.store.latest(f.f.f.node,1)));}
 @Test void actualFutureStaleConflictingSequenceAndDamagedNativeStorageNeverIssueFreshAck()throws Exception{code(post(f.token,"",f.raw(f.f.now.plusNanos(1000),1,10),false),422,"validation");assertEquals(200,post(f.token,"",f.raw(f.f.now,1,10),false).statusCode());code(post(f.token,"",f.raw(f.f.now,1,11),false),409,"snapshot_conflict");f.at.set(f.f.now.plusSeconds(600));code(post(f.token,"",f.raw(f.f.now.plusSeconds(1),2,11),false),422,"validation");f.f.f.jdbc.update("UPDATE runtime_settings SET revision=0 WHERE setting_key=?",JdbcCollectorHostMemory.key(f.f.f.node));var damaged=post(f.token,"",f.raw(f.f.now,1,10),false);code(damaged,503,"temporarily_unavailable");assertEquals("1",damaged.headers().firstValue("Retry-After").orElseThrow());}
 @Test void explicitlyDisabledMemoryRouteDoesNotConsumeOrPersistSnapshot()throws Exception{app.close();start(false);assertTrue(app.getBeansOfType(CollectorHostMemoryController.class).isEmpty());assertEquals(403,post(f.token,"",f.raw(f.f.now,1,10),false).statusCode());assertNull(f.f.f.tx.execute(s->f.f.store.latest(f.f.f.node,1)));}
}
